<script setup lang="ts">
import {can,firstAllowed} from './session'
import {useTableWidths} from './tableWidths'
const tableWidths=useTableWidths('FinancePanel')

import {ref,onMounted,onUnmounted,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {api} from './session'
import {displayCurrency} from './currency'
import FinanceSummaryPanel from './FinanceSummaryPanel.vue'
const props=defineProps<{store:string}>(),rows=ref<any[]>([]),summary=ref<any[]>([]),q=ref(''),market=ref(''),markets=ref<string[]>([]),status=ref('RELEASED'),page=ref(1),pageSize=ref(25),total=ref(0),busy=ref(false),error=ref(''),selected=ref<any>(null),detailOpen=ref(false),view=ref(firstAllowed('finance',['records', 'summary'])),days=ref<number|string>(1)
const dateBasis=ref('posted'),dateRange=ref<string[]>([]),category=ref(''),categoryMenuOpen=ref(false),categories=ref<{value:string,label:string,help:string}[]>([])
const percent=(v:any)=>v==null?'—':Number(v).toFixed(2)+'%'
const selectedStore=ref(props.store),stores=ref<string[]>([]),fx=ref<any>(null)
const money=(v:any)=>v==null?'—':new Intl.NumberFormat('zh-CN',{style:'currency',currency:displayCurrency.value}).format(Number(v))
const statusName:Record<string,string>={RELEASED:'已释放',DEFERRED:'暂缓',DEFERRED_RELEASED:'暂缓历史（已释放）',UNKNOWN:'未返回',queued:'排队中',running:'同步中',succeeded:'已完成',failed:'失败'}
const fmt=(v:any)=>v==null?'—':Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})
const time=(v:string)=>v?new Date(v).toLocaleString('zh-CN'):'—'
let seq=0
async function load(){if(!can('finance.records'))return;if(days.value==='custom'&&dateRange.value?.length!==2){ElMessage.warning('请选择完整日期范围');return;}const id=++seq;busy.value=true;try{const p=new URLSearchParams({store:selectedStore.value,q:(q.value??'').trim(),status:status.value??'',marketplace:market.value??'',page:String(page.value),page_size:String(pageSize.value),currency:displayCurrency.value});p.set('date_basis',dateBasis.value);p.set('transaction_type',category.value??'');if(days.value==='custom'){p.set('start',dateRange.value[0]);p.set('end',dateRange.value[1])}else p.set('days',String(days.value));const d=await api('/finance/transactions?'+p);if(id===seq){if(!Array.isArray(d.transaction_types))throw new Error('当前后端尚未更新交易类型及金额明细接口，请更新后端服务后刷新页面，无需重新同步已有流水');rows.value=d.rows;total.value=d.total;categories.value=d.transaction_types;summary.value=d.display_summary;fx.value=d.fx;error.value=''}}catch(e){if(id===seq)error.value=(e as Error).message}finally{if(id===seq)busy.value=false}}
function search(){page.value=1;load()}
async function detail(row:any){try{selected.value=await api('/finance/transactions/'+row.id);detailOpen.value=true}catch(e){ElMessage.error((e as Error).message)}}
function flatten(items:any[],prefix=''):any[]{return (items||[]).flatMap(x=>{const label=prefix?prefix+' / '+(x.label_cn||x.breakdownType):(x.label_cn||x.breakdownType);return [{label,amount:x.breakdownAmount?.currencyAmount,currency:x.breakdownAmount?.currencyCode},...flatten(x.breakdowns,label)]})}
onMounted(async()=>{const o=await api('/options');markets.value=o.order_markets||Object.keys(o.markets||{});stores.value=o.stores;await load()})
onUnmounted(()=>{seq++});watch(()=>props.store,v=>{selectedStore.value=v});watch(selectedStore,()=>{page.value=1;q.value='';load()});watch(displayCurrency,search)
</script>
<template><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="finance-toolbar"><el-radio-group v-model="view"><el-radio-button v-if="can('finance.records')" value="records">回款查询</el-radio-button><el-radio-button v-if="can('finance.summary')" value="summary">财务汇总</el-radio-button></el-radio-group></div>
<template v-if="view==='records'">
<section class="panel finance-records">
 <form class="filters finance-filters" @submit.prevent="search">
  <el-input v-model="q" placeholder="输入完整亚马逊订单号" clearable class="keyword"/>
  <el-select v-model="selectedStore" aria-label="回款店铺"><el-option v-for="s in stores" :key="s" :label="s" :value="s"/></el-select>
  <el-select v-model="market" :value-on-clear="''" aria-label="站点" placeholder="全部站点" clearable style="width:135px"><el-option v-for="m in markets" :key="m" :value="m" :label="m"/></el-select>
  <el-select v-model="category" :value-on-clear="''" @visible-change="categoryMenuOpen=$event" aria-label="交易类型" placeholder="全部交易类型" clearable style="width:180px"><el-option v-for="c in categories" :key="c.value" :value="c.value" :label="c.label"><el-tooltip :content="c.help" :disabled="!categoryMenuOpen" placement="right"><span style="display:block">{{c.label}}</span></el-tooltip></el-option></el-select>
  <el-select v-model="status" :value-on-clear="''" aria-label="回款状态" placeholder="全部回款状态" clearable style="width:180px"><el-option v-for="s in ['RELEASED','DEFERRED','DEFERRED_RELEASED']" :key="s" :label="statusName[s]" :value="s"/></el-select>
  <el-select v-model="dateBasis" aria-label="时间类型" style="width:135px"><el-option value="posted" label="入账时间"/><el-option value="order" label="订单时间"/></el-select>
  <el-select v-model="days" aria-label="日期范围" @change="days!=='custom'&&search()" style="width:145px"><el-option v-for="d in [1,3,7,14,30,90,180,365]" :key="d" :value="d" :label="`最近${d}天`"/><el-option value="custom" label="指定时间"/></el-select>
  <el-date-picker v-if="days==='custom'" v-model="dateRange" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" range-separator="至" style="width:290px;flex:none"/>
  <el-button native-type="submit" type="primary">查询</el-button><TableReset table-key="FinancePanel/table-1"/>
 </form>
 <p class="metrics-note">按所选时间口径筛选，入账时间降序展示。最近1天为过去24小时；指定日期含首尾两天，按站点当地日期（未返回站点时按欧洲柏林时间）。订单时间筛选不含未关联订单的流水。展示币种：{{displayCurrency}} · 汇率参考日期：{{fx?.date||'待同步'}}。</p>
 <p class="metrics-note">销售额＝销售收入（不含税）＋商品税，商品税不与商城代扣税相抵；费用及退款保留原始正负号；无销售的费用流水销售额为0，退款、销售额小于等于0或缺失时利润率显示—。毛利润＝交易净额－商品成本－头程运费，缺失成本及头程按0估算，已释放退款毛利润＝关联原销售回款（可含暂缓）＋退款净额－未退回或不可售商品的成本及头程；退回可售部分不扣成本。退回状态待核实时不计算毛利润；暂缓及历史记录不计算利润。退款毛利润是订单损益口径，不可与原销售毛利润重复汇总。</p>
 <div class="finance-totals"><div v-for="s in summary" :key="s.status"><span>{{statusName[s.status]}} · {{displayCurrency}}</span><b>{{money(s.amount)}}</b><small>{{s.count}} 笔 · {{s.status==='DEFERRED_RELEASED'?'历史记录，勿重复计入':'已同步流水净额'}}<template v-if="s.unknown"> · 有金额未返回</template><template v-if="s.missing_currencies?.length"> · 汇率待补齐</template></small></div></div>
 <el-table border data-width-key="FinancePanel/table-1" @header-dragend="(width:number,_old:number,column:any)=>tableWidths.resize('table-1',width,column)" @header-contextmenu="(column:any,event:MouseEvent)=>tableWidths.resetColumn('table-1',column,event)" :data="rows" v-loading="busy" @row-dblclick="detail" row-key="id">
  <el-table-column column-key="order_date" label="订单时间" :width="tableWidths.width('table-1','order_date',180)"><template #default="{row}">{{time(row.order_date)}}</template></el-table-column>
  <el-table-column column-key="column-2" label="入账时间" :width="tableWidths.width('table-1','column-2',180)"><template #default="{row}">{{time(row.posted_at)}}</template></el-table-column>
  <el-table-column column-key="column-3" label="订单号" :width="tableWidths.width('table-1','column-3',205)"><template #default="{row}"><button v-if="row.order_id" class="order-link" @click="q=row.order_id;search()">{{row.order_id}}</button><span v-else>非订单流水</span></template></el-table-column>
  <el-table-column column-key="marketplace" prop="marketplace" label="站点" :width="tableWidths.width('table-1','marketplace',75)"/>
  <el-table-column column-key="column-5" label="订单商品 / 数量" :width="tableWidths.width('table-1','column-5',260)"><template #default="{row}"><div v-for="(item,n) in row.order_items" :key="n" class="finance-sku"><span>{{item.sku}} <b>× {{item.quantity??'待返回'}}</b></span></div><span v-if="!row.order_items?.length" class="muted">{{row.order_id?'商品待同步':'非订单流水'}}</span></template></el-table-column>
  <el-table-column column-key="transaction_type_cn" label="交易类型" :width="tableWidths.width('table-1','transaction_type_cn',140)"><template #default="{row}"><el-tooltip :content="row.category_help+' 亚马逊原始交易类型：'+row.transaction_type" placement="top"><span class="finance-type">{{row.transaction_type_cn}} · {{row.transaction_type}}</span></el-tooltip></template></el-table-column>
  <el-table-column column-key="column-7" label="状态" :width="tableWidths.width('table-1','column-7',130)"><template #default="{row}">{{statusName[row.status]||row.status}}</template></el-table-column>
  <el-table-column column-key="sales_amount" label="销售额" :width="tableWidths.width('table-1','sales_amount',140)" align="right"><template #default="{row}">{{money(row.sales_amount)}}</template></el-table-column>
  <el-table-column column-key="sales_ex_tax" label="销售收入（不含税）" :width="tableWidths.width('table-1','sales_ex_tax',170)" align="right"><template #default="{row}">{{money(row.sales_ex_tax)}}</template></el-table-column>
  <el-table-column column-key="product_tax" label="商品税" :width="tableWidths.width('table-1','product_tax',170)" align="right"><template #default="{row}">{{money(row.product_tax)}}</template></el-table-column>
  <el-table-column column-key="fulfillment_fee" label="物流基础服务费" :width="tableWidths.width('table-1','fulfillment_fee',170)" align="right"><template #default="{row}">{{money(row.fulfillment_fee)}}</template></el-table-column>
  <el-table-column column-key="sales_commission" label="销售佣金" :width="tableWidths.width('table-1','sales_commission',170)" align="right"><template #default="{row}">{{money(row.sales_commission)}}</template></el-table-column>
  <el-table-column column-key="column-8" label="交易净额" :width="tableWidths.width('table-1','column-8',150)" align="right"><template #default="{row}"><b :class="{negative:Number(row.amount)<0}">{{money(row.converted?.amount)}}</b><div class="cell-sub">原币 {{row.currency}} {{fmt(row.amount)}}</div></template></el-table-column>
  <el-table-column column-key="return_status" label="退回状态" :width="tableWidths.width('table-1','return_status',190)"><template #default="{row}"><span>{{row.return_status||'—'}}</span><small v-if="row.return_checked_at" class="cell-sub">核实于 {{time(row.return_checked_at)}}</small></template></el-table-column>
  <el-table-column column-key="settlement_margin" :width="tableWidths.width('table-1','settlement_margin',150)" align="right"><template #header><el-tooltip content="交易净额 ÷ 销售额 × 100%；退款、销售额小于等于0或缺失时不计算"><span class="finance-type">结算利润率 ⓘ</span></el-tooltip></template><template #default="{row}">{{percent(row.settlement_margin)}}</template></el-table-column>
  <el-table-column column-key="settlement_gross_profit" :width="tableWidths.width('table-1','settlement_gross_profit',170)" align="right"><template #header><el-tooltip content="交易净额－商品成本－商品头程运费。按流水商品数量及当前维护的本地成本估算，缺失项按0；不会重复扣除已在交易净额中的平台费用。已释放退款关联原销售回款，仅未退回或不可售部分扣成本及头程。"><span class="finance-type">毛利润 ⓘ</span></el-tooltip></template><template #default="{row}"><el-tooltip :content="(row.original_sale_net!=null?'关联原销售回款 '+money(row.original_sale_net)+'；':'')+'商品成本 '+money(row.purchase_cost)+'；头程运费 '+money(row.freight_cost)+'。'+(row.calculation_notes||[]).join('；')"><span :class="{negative:Number(row.settlement_gross_profit)<0}">{{money(row.settlement_gross_profit)}}<small v-if="row.cost_estimated" class="cell-sub">含估算成本</small></span></el-tooltip><el-tooltip v-if="row.calculation_notes?.length" :content="row.calculation_notes.join('；')"><span class="finance-type cell-sub">计算说明 ⓘ</span></el-tooltip></template></el-table-column>
  <el-table-column column-key="settlement_gross_margin" :width="tableWidths.width('table-1','settlement_gross_margin',150)" align="right"><template #header><el-tooltip content="毛利润 ÷ 销售额 × 100%；退款、销售额小于等于0或缺失时不计算"><span class="finance-type">毛利率 ⓘ</span></el-tooltip></template><template #default="{row}">{{percent(row.settlement_gross_margin)}}</template></el-table-column>
  <el-table-column column-key="column-9" label="操作" fixed="right" :width="100"><template #default="{row}"><el-button link type="primary" @click="detail(row)">费用明细</el-button></template></el-table-column>
  <template #empty><el-empty description="尚无匹配流水，请调整日期或筛选条件"/></template>
 </el-table>
 <div class="table-footer"><span>按首页币种展示 · 净额不是银行到账；毛利按当前成本估算</span><AppPagination v-model:current-page="page" :total="total" @change="load" v-model:page-size="pageSize"/></div>
</section>
</template>
<FinanceSummaryPanel v-else-if="view==='summary'" :store="props.store"/>
<el-drawer v-model="detailOpen" title="回款及扣费明细" size="720px"><template v-if="selected"><h2>{{selected.order_id||'非订单流水'}}</h2><p>{{selected.currency}} {{fmt(selected.amount)}} · {{statusName[selected.status]||selected.status}}</p><p class="muted">流水编号 {{selected.transaction_id}}</p><p :title="selected.data.description">{{selected.data.description_cn}}</p><h3>订单包含商品</h3><p v-for="(item,n) in selected.order_items" :key="n">{{item.sku}} × {{item.quantity??'待返回'}}</p><h3>交易费用结构</h3><template v-if="true"><TableReset table-key="FinancePanel/table-3"/><el-table border data-width-key="FinancePanel/table-3" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-3', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-3', column, event)" :data="flatten(selected.data.breakdowns)"><el-table-column :column-key="'label'" :width="tableWidths.width('table-3', 'label', undefined)" prop="label" label="费用路径" min-width="260" align="center"/><el-table-column :column-key="'column-2'" :width="tableWidths.width('table-3', 'column-2', undefined)" label="金额" align="center"><template #default="{row}">{{row.currency}} {{fmt(row.amount)}}</template></el-table-column></el-table></template><p class="metrics-note">上下级项目存在包含关系，不能把所有行重复相加。</p><div v-for="(i,n) in selected.data.items" :key="n"><h3>{{i.description||'商品明细 '+(Number(n)+1)}}</h3><p v-for="(c,k) in i.contexts" :key="k" class="muted">{{c.sku||c.asin||''}}<template v-if="c.quantityShipped!=null"> · 数量 {{c.quantityShipped}}</template></p><template v-if="true"><TableReset table-key="FinancePanel/table-4"/><el-table border data-width-key="FinancePanel/table-4" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-4', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-4', column, event)" :data="flatten(i.breakdowns)"><el-table-column :column-key="'label'" :width="tableWidths.width('table-4', 'label', undefined)" prop="label" label="项目"/><el-table-column :column-key="'column-2'" :width="tableWidths.width('table-4', 'column-2', undefined)" label="金额" align="center"><template #default="{row}">{{row.currency}} {{fmt(row.amount)}}</template></el-table-column></el-table></template></div></template></el-drawer></template>

<style scoped>.finance-type{cursor:help;border-bottom:1px dotted #83988e}.finance-filters{display:flex;flex-wrap:wrap;overflow:visible}.finance-filters>.keyword{width:220px!important;flex:0 0 220px}.finance-filters>.el-select{width:160px!important;flex:0 0 160px}.finance-filters>.el-button{width:auto;flex-shrink:0}.cell-sub{display:block}</style>
